/**
 * Parity Test Suite: Python vs JavaScript Engine.
 * Loads packs/golden_test_vectors.json generated by Python engine
 * and asserts that the JavaScript client-side engine port produces identical output.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { BKTEngine } from './src/engine/bkt.js';
import { SpacedRepetitionScheduler } from './src/engine/scheduler.js';
import { HypothesisEngine } from './src/engine/hypothesis.js';
import { RuleSequencer } from './src/engine/sequencer.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const vectorPath = path.resolve(__dirname, '..', 'packs', 'golden_test_vectors.json');
if (!fs.existsSync(vectorPath)) {
  console.error(`ERROR: Golden test vectors not found at ${vectorPath}. Run python scripts/generate_golden_vectors.py first.`);
  process.exit(1);
}

const vectors = JSON.parse(fs.readFileSync(vectorPath, 'utf-8'));
let testCount = 0;
let passedCount = 0;

function assertEqual(actual, expected, message) {
  testCount++;
  if (typeof actual === 'number' && typeof expected === 'number') {
    if (Math.abs(actual - expected) > 0.0002) {
      console.error(`FAIL: ${message} -> expected ${expected}, got ${actual}`);
      process.exit(1);
    }
  } else {
    if (actual !== expected) {
      console.error(`FAIL: ${message} -> expected ${expected}, got ${actual}`);
      process.exit(1);
    }
  }
  passedCount++;
}

console.log('=== SETU PYTHON <-> JAVASCRIPT ENGINE PARITY TEST SUITE ===');

// 1. BKT Sequence Parity
console.log('\nTesting BKT Update Parity...');
const bkt = new BKTEngine({ prior: 0.2, learn: 0.15, guess: 0.2, slip: 0.1 });
for (const step of vectors.bkt_sequence) {
  const actual = bkt.update(step.input_mastery, step.is_correct);
  assertEqual(actual, step.output_mastery, `BKT Step ${step.step} (input: ${step.input_mastery}, is_correct: ${step.is_correct})`);
}
console.log(`✓ All ${vectors.bkt_sequence.length} BKT update steps passed with exact parity.`);

// 2. SM-2 Spaced Repetition Parity
console.log('\nTesting SM-2 Spaced Repetition Parity...');
const scheduler = new SpacedRepetitionScheduler();
let state = {
  student_id: 'test_vec',
  concept_id: 'c8_leq',
  interval_days: 1.0,
  ease_factor: 2.5,
  consecutive_successes: 0
};
const fixedTime = '2026-01-01T12:00:00Z';
for (let i = 0; i < vectors.sm2_sequence.length; i++) {
  const expected = vectors.sm2_sequence[i];
  state = scheduler.scheduleNextReview(state, expected.quality, fixedTime);
  assertEqual(state.interval_days, expected.interval_days, `SM-2 Step ${i} interval_days`);
  assertEqual(state.ease_factor, expected.ease_factor, `SM-2 Step ${i} ease_factor`);
  assertEqual(state.consecutive_successes, expected.consecutive_successes, `SM-2 Step ${i} consecutive_successes`);
}
console.log(`✓ All ${vectors.sm2_sequence.length} SM-2 repetition steps passed with exact parity.`);

// 3. Hypothesis & Evidence Band Parity
console.log('\nTesting Hypothesis & Heuristic Evidence Band Parity...');
const hypEngine = new HypothesisEngine();
let hyp = hypEngine.openHypothesis('test_vec', 'c7_math_integers_add_sub', 'tag_sign_error_on_transposition');

const probeDefs = [
  { id: 'q_probe_01', concept: 'c7_math_integers_add_sub', is_supporting: true },
  { id: 'q_probe_02', concept: 'c7_math_integers_add_sub', is_supporting: true },
  { id: 'q_probe_03', concept: 'c7_math_integers_add_sub', is_supporting: false }
];

for (let i = 0; i < vectors.hypothesis_sequence.length; i++) {
  const expected = vectors.hypothesis_sequence[i];
  const p = probeDefs[i];
  hyp = hypEngine.addProbeResult(hyp, p.id, p.concept, p.is_supporting);
  assertEqual(hyp.heuristic_score, expected.heuristic_score, `Hypothesis Step ${i} heuristic_score`);
  assertEqual(hyp.evidence_band, expected.evidence_band, `Hypothesis Step ${i} evidence_band`);
  assertEqual(hyp.status, expected.status, `Hypothesis Step ${i} status`);
}
console.log(`✓ All ${vectors.hypothesis_sequence.length} Hypothesis evidence band steps passed with exact parity.`);

// 4. Rule Sequencer Parity
console.log('\nTesting Rule Sequencer Parity...');
const sequencer = new RuleSequencer();
for (let i = 0; i < vectors.sequencer_results.length; i++) {
  const expected = vectors.sequencer_results[i];
  const dec = sequencer.evaluate(expected.input);
  assertEqual(dec.action, expected.action, `Sequencer case ${i} action`);
  assertEqual(dec.rule_id, expected.rule_id, `Sequencer case ${i} rule_id`);
}
console.log(`✓ All ${vectors.sequencer_results.length} Sequencer decision cases passed with exact parity.`);

// 5. Multi-Concept Mastery Isolation Parity (FIX 3)
console.log('\nTesting Multi-Concept Mastery Isolation Parity (FIX 3)...');
if (vectors.multi_concept_mastery_isolation) {
  const mc = vectors.multi_concept_mastery_isolation;
  const bktEngine = new BKTEngine();
  const c7Res = bktEngine.update(mc.attempt_concept_initial_mastery, mc.attempt_is_correct);
  assertEqual(c7Res, mc.expected_attempt_concept_mastery, 'Attempt concept mastery update');
  assertEqual(mc.plan_concept_initial_mastery, mc.expected_plan_concept_mastery, 'Plan concept mastery isolation');
  console.log('✓ Multi-concept mastery isolation verified: attempt updates question concept without altering plan concept.');
}

console.log(`\n============================================================`);
console.log(`SUCCESS: 100% PARITY VERIFIED (${passedCount}/${testCount} checks passed).`);
console.log(`Python and JavaScript engines are mathematically and logically aligned.`);
console.log(`============================================================\n`);
